using FluentAssertions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class GeneratedFormatterHonoursTypeAttributesTests
{
    private readonly ITestOutputHelper logger;

    public GeneratedFormatterHonoursTypeAttributesTests(ITestOutputHelper logger)
    {
        this.logger = logger;
    }

    [Fact]
    public async Task DataContractAttributesOnReferencedTypeAreHonoured()
    {
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.Latest);

        string projectASource = """
            using System.Runtime.Serialization;

            namespace ProjectA
            {
                [DataContract]
                public class MyType
                {
                    [DataMember(Order = 0)]
                    public int A { get; set; }

                    [IgnoreDataMember]
                    public string Secret { get; set; }

                    public string Unmarked { get; set; }
                }
            }
            """;

        CSharpCompilation projectA = CSharpCompilation.Create(
            "ProjectA",
            new[] { CSharpSyntaxTree.ParseText(projectASource, parseOptions) },
            framework,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        using MemoryStream stream = new MemoryStream();
        var emitResult = projectA.Emit(stream);
        emitResult.Success.Should().BeTrue(string.Join(Environment.NewLine, emitResult.Diagnostics));
        MetadataReference projectARef = MetadataReference.CreateFromImage(stream.ToArray());

        string projectBSource = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                [GeneratedMessagePackFormatter]
                public partial class MyTypeFormatter : IMessagePackFormatter<ProjectA.MyType> { }

                [GeneratedMessagePackResolver]
                partial class MyResolver { }
            }
            """;

        List<MetadataReference> references = new List<MetadataReference>(framework);
        references.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        references.Add(projectARef);

        CSharpCompilation projectB = CSharpCompilation.Create(
            "ProjectB",
            new[] { CSharpSyntaxTree.ParseText(projectBSource, parseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver = driver.RunGenerators(projectB);
        GeneratorDriverRunResult result = driver.GetRunResult();

        foreach (GeneratorRunResult r in result.Results)
        {
            r.Exception.Should().BeNull();
        }

        List<string> generated = result.GeneratedTrees.Select(t => t.GetText().ToString()).ToList();
        foreach (string g in generated)
        {
            this.logger.WriteLine(g);
        }

        generated.Should().Contain(g => g.Contains("partial class MyTypeFormatter"), "the generator must write the formatter body into the user-declared partial class");

        string all = string.Join(Environment.NewLine, generated);
        all.Should().NotContain("Secret", "[IgnoreDataMember] on the formatted type must be honoured");
        all.Should().NotContain("Unmarked", "a [DataContract] type only serializes [DataMember] members");
    }
}
